import { defineConfig } from 'wxt';

/**
 * Form Auto Filler v1 - WXT build config.
 * Manifest is generated by WXT; never hand-edit .output/chrome-mv3/manifest.json.
 * Permission whitelist: activeTab / scripting / storage. No host_permissions.
 * The main content logic is an unlisted script injected on user gesture,
 * so no static content_scripts / matches are declared here.
 */
export default defineConfig({
  modules: ['@wxt-dev/module-vue'],
  srcDir: '.',
  outDir: '.output',
  // Vite's modulepreload polyfill contains a fetch() call for local chunks.
  // Chromium 120 has native modulepreload support, so disabling the polyfill
  // keeps the shipped bundle free of ANY outbound network API (ARCH 15.1).
  vite: () => ({
    build: { modulePreload: { polyfill: false } },
  }),
  manifest: {
    name: 'Form Auto Filler',
    version: '1.0.0',
    description: 'Fill test data into forms on test environments. Does not submit.',
    minimum_chrome_version: '120',
    permissions: ['activeTab', 'scripting', 'storage'],
    action: {
      default_title: 'Form Auto Filler',
    },
    commands: {
      'open-plan': {
        suggested_key: { default: 'Alt+Shift+F', mac: 'Alt+Shift+F' },
        description: 'Open the fill plan preview',
      },
      'scope-current-form': {
        suggested_key: { default: 'Alt+Shift+G', mac: 'Alt+Shift+G' },
        description: 'Limit detection to the current form',
      },
      'scope-current-row': {
        suggested_key: { default: 'Alt+Shift+H', mac: 'Alt+Shift+H' },
        description: 'Limit detection to the focused form row',
      },
      'open-picker': {
        suggested_key: { default: 'Alt+Shift+P', mac: 'Alt+Shift+P' },
        description: 'Open the field picker',
      },
    },
    // WXT derives options_ui from entrypoints/options/index.html. The
    // open_in_tab flag is set by the "manifest.open_in_tab" meta tag there,
    // because WXT overwrites manifest.options_ui when it discovers the page.
    options_ui: {
      page: 'options.html',
    },
    content_security_policy: {
      extension_pages: "script-src 'self' 'wasm-unsafe-eval'; object-src 'self'",
    },
  },
});
